char bytes[2];
ffmt::detail::iterator_sink<char*, char> sink{bytes, 2};
sink.repeat('x', 7); // bytes == {'x', 'x'}; written == 2; required == 7

#include <ffmt/detail/checked.hpp>
char buffer[64];
auto result = ffmt::format_to(buffer, "{:.21g}", 1.234567890123456789L);
// Conversion uses the native long-double representation; it does not narrow to double.

#include <ffmt/detail/checked.hpp>
using U = unsigned __int128; // when the compiler supplies this type
char buffer[64];
auto result = ffmt::format_to(buffer, "{:#x}", U(1) << 100);
// Writes the full native value, "0x10000000000000000000000000".

#include <ffmt/detail/checked.hpp>
char buffer[64];
auto size = ffmt::detail::portable_shortest(
    buffer, std::numeric_limits<double>::denorm_min());
// buffer[0..size) is "5e-324", matching the independent fmt oracle.

#include <ffmt/detail/checked.hpp>
char buffer[2];
auto result = ffmt::format_to_n(buffer, sizeof buffer, "{:.2000f}", 0.125);
// Stores "0."; result.written == 2; result.required == 2002.

#include <ffmt/detail/checked.hpp>
struct status { unsigned code; };
constexpr auto format_as(status value) { return value.code; }
// ffmt::format_to(buffer, "{:#x}", status{42}) writes "0x2a".
// The same mapped value can supply a dynamic integer width.

#include <ffmt/detail/checked.hpp>
struct point { int value; };
template <class Char>
struct ffmt::formatter<point, Char> : ffmt::formatter<int, Char> {
  template <class Context>
  auto format(const point& p, Context& ctx) const {
    return ffmt::formatter<int, Char>::format(p.value, ctx);
  }
};
// Formatting point{42} with "{:04x}" now writes "002a".
// Inherited parse() checks the same specs as the integer formatter.

Inside an existing ffmt::formatter<point> specialization:
static constexpr auto format(point p) {
  return ffmt::formatted<"({}, {})", int, int>{{p.x, p.y}};
}
// Formatting point{2, 7} with "{}" continues to write "(2, 7)".
// test_core_legacy.cpp checks the corresponding narrow and wide output.

Given the handler in test_core_parsing.cpp:
ffmt::detail::walk_format<char>("{{{:04x}}}", events);
// Receives two literal braces and one argument with width 4/type x.
// "{0} {}" instead returns invalid_format for mixed index modes.

#include <ffmt/detail/checked.hpp> // public base.hpp migrates later
char buffer[2];
auto result = ffmt::format_to_n(buffer, sizeof buffer, "{:04x}", 42);
// buffer == {'0', '0'}; result.written == 2; result.required == 4

#include <ffmt/detail/checked.hpp> // base.hpp switches in the migration PR
auto result = ffmt::try_print("a{}b", char(0));
// The default host counted transport emits all three bytes: a, NUL, b.
// A transport without counted-byte support reports its limitation.

#include <ffmt/detail/checked.hpp>
char buffer[32];
auto result = ffmt::format_to(buffer, "{:─^9}", "é");
// Bytes encode "────é────": display width 9, rather than padding by UTF-8 byte count.

#include <ffmt/chrono.hpp>
ffmt::println("{:%T}", std::chrono::milliseconds{-123456}); // -00:02:03.456
ffmt::println("{:%G-W%V-%u}", std::chrono::year{2021}/1/1); // 2020-W53-5

#include <ffmt/enum.hpp>
namespace status_example {
using ffmt::enums::format_as;
enum class status : int { warning = -3 };
}
ffmt::println("{:+05}", status_example::status::warning); // -0003

